import {readFile,writeFile} from 'node:fs/promises';
import {createMcpServer} from '../src/server.mjs';

const broker={};
const server=createMcpServer(broker);
const commands=broker.toolCatalog();
await server.close();

const quote=value=>JSON.stringify(value).replace(/\\u([0-9a-f]{4})/gi,'\\u{$1}');
const rows=commands.map(({name,category,grant,description})=>
 `\t{ name = ${quote(name)}, category = ${quote(category)}, grant = ${quote(grant)}, description = ${quote(description)} },`);
const source=[
 '--!strict',
 '-- Generated by mcp/scripts/generate-tool-catalog.mjs.',
 '',
 'local commands = {',
 ...rows,
 '}',
 '',
 'return { InitDeps = function() end, InitAfterMain = function() end, Main = function() return commands end }',
 '',
].join('\n');
const file=new URL('../../src/Apps/AIBridge/Services/BridgeCommandCatalog.lua',import.meta.url);
if(process.argv.includes('--check')){
 const normalize=text=>text.replace(/"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|\s+|,(?=\s*})/g, token=>{
  if(token[0]!=='"'&&token[0]!=="'")return '';
  return JSON.stringify(token.slice(1,-1).replace(/\\\\|\\['"]/g, escape=>escape==='\\\\'?escape:escape[1]));
 });
 if(normalize(await readFile(file,'utf8'))!==normalize(source))throw Error('Run npm run catalog to refresh the bundled Dex command list');
}else await writeFile(file,source);
